     1	import { titleCaseWords } from "@/lib/string-utils";
     2	
     3	/**
     4	 * The value-format directives a `data` binding (or a table column) can request.
     5	 * Each maps a raw scalar to a display string. Domain-agnostic on purpose — the
     6	 * renderer knows how to *format* a currency/date/enum, but never which entity
     7	 * field is a currency; that decision comes from the JSON-Schema annotation
     8	 * (`format`, `enum`, `x-currency`) resolved by whoever builds the binding.
     9	 *
    10	 * `url` returns a compact host+path label; the caller decides whether to wrap it
    11	 * in an anchor (the DSL's link-ness is a separate concern from its label).
    12	 */
    13	export type ValueFormat =
    14		| "currency"
    15		| "date"
    16		| "url"
    17		| "enum"
    18		| "boolean"
    19		| "number"
    20		| "auto"
    21		| "text";
    22	
    23	const DATE_STRING =
    24		/^\d{4}-\d{2}-\d{2}(?:[tT ]\d{2}:\d{2}(?::\d{2}(?:\.\d+)?)?(?:Z|[+-]\d{2}:?\d{2})?)?$/;
    25	
    26	export function looksLikeDateString(value: string): boolean {
    27		return DATE_STRING.test(value);
    28	}
    29	
    30	export function isHttpUrl(value: string): boolean {
    31		if (!/^https?:\/\//i.test(value)) return false;
    32		try {
    33			const url = new URL(value);
    34			return url.protocol === "http:" || url.protocol === "https:";
    35		} catch {
    36			return false;
    37		}
    38	}
    39	
    40	function formatCurrency(value: number): string {
    41		return new Intl.NumberFormat("en-US", {
    42			style: "currency",
    43			currency: "USD",
    44			notation: value >= 1000 ? "compact" : "standard",
    45			maximumFractionDigits: value >= 1_000_000_000 ? 1 : 0,
    46		}).format(value);
    47	}
    48	
    49	function formatNumber(value: number): string {
    50		return new Intl.NumberFormat("en-US", {
    51			maximumFractionDigits: Number.isInteger(value) ? 0 : 2,
    52		}).format(value);
    53	}
    54	
    55	function formatDate(value: string): string {
    56		const date = new Date(value);
    57		if (Number.isNaN(date.getTime())) return value;
    58		return date.toLocaleDateString("en-US", {
    59			month: "short",
    60			day: "numeric",
    61			year: "numeric",
    62		});
    63	}
    64	
    65	export function formatUrlLabel(value: string): string {
    66		try {
    67			const url = new URL(value);
    68			const host = url.hostname.replace(/^www\./i, "");
    69			const path =
    70				url.pathname && url.pathname !== "/" ? url.pathname.replace(/\/$/, "") : "";
    71			return `${host}${path}`;
    72		} catch {
    73			return value;
    74		}
    75	}
    76	
    77	function humanizeToken(value: string): string {
    78		return titleCaseWords(value.replace(/[_-]+/g, " "));
    79	}
    80	
    81	/**
    82	 * Format a single scalar per an explicit directive.
    83	 *
    84	 * `format` omitted or `"text"` = raw passthrough (`String(value)`) — this is the
    85	 * safe default so existing bindings never silently reformat. `"auto"` opts into
    86	 * shape inference (dates/urls, never currency). Specific formats force that
    87	 * treatment. Booleans always render Yes/No; non-scalars are JSON-stringified.
    88	 */
    89	export function formatValue(value: unknown, format?: ValueFormat): string {
    90		if (value === null || value === undefined) return "";
    91	
    92		if (typeof value === "boolean") return value ? "Yes" : "No";
    93	
    94		if (typeof value === "number") {
    95			if (format === "currency") return formatCurrency(value);
    96			if (format === undefined || format === "text") return String(value);
    97			return formatNumber(value);
    98		}
    99	
   100		if (typeof value !== "string") return JSON.stringify(value);
   101	
   102		switch (format) {
   103			case "currency":
   104				return formatCurrency(Number(value));
   105			case "date":
   106				return formatDate(value);
   107			case "url":
   108				return formatUrlLabel(value);
   109			case "enum":
   110				return humanizeToken(value);
   111			case "number":
   112				return formatNumber(Number(value));
   113			case "auto": {
   114				// Infer date/url from the value's shape (the table's prior auto
   115				// behavior), but never currency.
   116				if (isHttpUrl(value)) return formatUrlLabel(value);
   117				if (looksLikeDateString(value)) return formatDate(value);
   118				return value;
   119			}
   120			default:
   121				// undefined | "text" → raw passthrough (no silent reformatting).
   122				return value;
   123		}
   124	}
