   505	// Render a single JSON node
   506	function renderNode(
   507	  node: JsonNode,
   508	  context: RenderContext,
   509	  key?: string | number,
   510	): React.ReactNode {
   511	  // Text node
   512	  if (node.type === 'text') {
   513	    return (node as TextNode).content;
   514	  }
   515	
   516	  // Data binding
   517	  if (node.type === 'data') {
   518	    const binding = node as DataBinding;
   519	    const value = getValueByPath(context.data, binding.path);
   520	    const resolved = value !== undefined ? value : binding.fallback;
   521	
   522	    // Editable mode: leaf data bindings become click-to-edit primitives. The
   523	    // template's binding path is the same path we expect on the server side
   524	    // for `submit_feedback` corrections, so it can be used directly. The raw
   525	    // value (not the formatted label) is edited — formatting is display-only.
   526	    if (context.onCorrection && resolved !== undefined && typeof resolved !== 'object') {
   527	      return (
   528	        <EditablePrimitive
   529	          value={resolved}
   530	          fieldPath={binding.path}
   531	          onCorrection={context.onCorrection}
   532	        />
   533	      );
   534	    }
   535	
   536	    // Schema-driven display formatting (currency/date/url/enum/…). When no
   537	    // format is set, formatValue auto-formats by shape (dates/urls) — matching
   538	    // the entity table's prior cell behavior — and never invents currency.
   539	    const str = formatValue(resolved, binding.format);
   540	    if (str.length > 100 && (str.includes('\n') || /[#*-]/.test(str))) {
   541	      const MarkdownComponent = componentRegistry.markdown;
   542	      return MarkdownComponent ? <MarkdownComponent content={str} /> : str;
   543	    }
   544	    return str;
   545	  }
   546	
   547	  // Conditional rendering
   548	  if (node.type === 'if') {
   549	    const conditional = node as ConditionalNode;
   550	    const conditionValue = getValueByPath(context.data, conditional.condition);
   551	    if (conditionValue) {
   552	      return renderNode(conditional.then, context, key);
   553	    } else if (conditional.else) {
   554	      return renderNode(conditional.else, context, key);
   555	    }
   556	    return null;
   557	  }
   558	
   559	  // Loop/iteration
   560	  if (node.type === 'each') {
   561	    const loop = node as LoopNode;
   562	    const items = getValueByPath(context.data, loop.items) as unknown[];
   563	    if (!Array.isArray(items)) return null;
   564	
   565	    return items.map((item, index) => {
   566	      const loopAs = loop.as;
   567	      const itemContext: RenderContext = {
   568	        ...context,
   569	        data: {
   570	          ...context.data,
   571	          [loopAs]: item,
   572	          [`${loopAs}Index`]: index,
   573	        },
   574	      };
