   595	  }
   596	
   597	  // Resolve a single prop value (data bindings, actions, or passthrough)
   598	  const resolveProp = (propValue: unknown): unknown => {
   599	    if (typeof propValue !== 'string') return propValue;
   600	    if (propValue.startsWith('@')) {
   601	      const actionName = propValue.slice(1);
