   159	/**
   160	 * Runtime boundary for a view authored by Lobu's own SPA host. These views can
   161	 * contain brokered tool actions because the parent frame pins every handler and
   162	 * sensitive argument. The source marker is added by McpAppFrame after the view
   163	 * is built; server-authored external views never receive it.
   164	 */
   165	function isSpaHostedInteractionView(value: unknown): value is UnknownRecord {
   166		if (
   167			!isRecord(value) ||
   168			value.version !== 1 ||
   169			value.source !== SPA_HOSTED_VIEW_SOURCE
   170		)
   171			return false;
   172		if (value.blocks === undefined && value.actions === undefined) return false;
   173		if (
   174			value.blocks !== undefined &&
   175			(!Array.isArray(value.blocks) ||
   176				value.blocks.length > 100 ||
   177				!value.blocks.every(isInteractionBlock))
   178		)
   179			return false;
   180		if (
   181			value.actions !== undefined &&
   182			(!Array.isArray(value.actions) ||
   183				value.actions.length > 10 ||
   184				!value.actions.every(isInteractionAction))
   185		)
   186			return false;
   187		if (!hasOptionalType(value, "title", "string")) return false;
   188		return (
   189			value.tone === undefined ||
   190			value.tone === "warning" ||
   191			value.tone === "default" ||
   192			value.tone === "bare"
   193		);
   194	}
