   198	 * LobuViewV1 and executable views authored by Lobu's own SPA frame host.
   199	 */
   200	export function isLobuView(value: unknown): value is UnknownRecord {
   201		if (isSpaHostedInteractionView(value)) return true;
   202		return isServerAuthoredLobuView(value);
   203	}
