   210		if (value.source !== undefined) return false;
   211		if (!Array.isArray(value.blocks) || value.blocks.length > 100) return false;
   212		if (!Array.isArray(value.actions) || value.actions.length > 10) return false;
   213		if (
   214			!value.blocks.every(isBlock) ||
   215			!value.actions.every(
