    12	 * resources and rendered by MCP Apps hosts (Slackbot, Claude, or our own web
    13	 * UI). Distinct from the SPA build (`vite.config.ts`): no router, one
    14	 * self-contained HTML per app (JS + CSS inlined via vite-plugin-singlefile),
    15	 * reusing the SPA's shadcn components + Tailwind v4 theme (each entry's
    16	 * `app.css` → `../../index.css`).
    17	 *
    18	 * One app builds per invocation, selected by `MCP_APP` (defaults to
    19	 * `interaction`, the single data-driven bundle). `build:mcp-apps` runs this once
    20	 * per app under `src/mcp-apps/`.
    21	 */
    22	const app = process.env.MCP_APP?.trim() || "interaction";
    23	const sharedStylesheetPath = path.resolve(__dirname, "src/index.css");
    24	const appStylesheetPath = path.resolve(
    25		__dirname,
    26		"src/mcp-apps",
    27		app,
    28		"app.css",
    29	);
    30	const omitExternalFontFaces: Plugin = {
