    37	/**
    38	 * Keep the shared theme as the source of truth, but narrow Tailwind's class
    39	 * discovery to the MCP app dependency surface. The SPA stylesheet explicitly
    40	 * scans the entire package and server public pages; carrying those unrelated
    41	 * utilities in a resources/read response wastes the embedding host's payload
    42	 * budget.
    43	 */
    44	const narrowTailwindSources: VitePlugin = {
    45		name: "mcp-app-narrow-tailwind-sources",
    46		enforce: "pre",
    47		transform(source, id) {
    48			const filename = id.split("?", 1)[0];
